'use strict';

// MODULES //

var incrsumprod = require( '@stdlib/stats-incr-sumprod' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes a sum of products, ignoring NaN values.
*
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnansumprod();
*
* var sum = accumulator( 2.0, 3.0 );
* // returns 6.0
*
* sum = accumulator( 1.0, -1.0 );
* // returns 5.0
*
* sum = accumulator( NaN, NaN );
* // returns 5.0
*
* sum = accumulator( 3, NaN );
* // returns 5.0
*
* sum = accumulator( 3.0, 4.0 );
* // returns 17.0
*
* sum = accumulator();
* // returns 17.0
*/
function incrnansumprod() {
	var sumprod = incrsumprod();
	return accumulator;

	/**
	* If provided input values, the accumulator function returns an updated sum. If not provided input values, the accumulator function returns the current sum.
	*
	* @private
	* @param {number} [x] - first value
	* @param {number} [y] - second value
	* @returns {(number|null)} sum-product or null
	*/
	function accumulator( x, y ) {
		if ( arguments.length === 0 || isnan( x ) || isnan( y ) ) {
			return sumprod();
		}
		return sumprod( x, y );
	}
}


// EXPORTS //

module.exports = incrnansumprod;
